MATCH (p:Player)-[r:PlaysFor]->(t:Team)
WHERE r.tenure = 'latest'
  AND p.college = 'Michigan State University'
  AND EXISTS { MATCH (p)-[:MentionedIn]->(:Document) }
  AND EXISTS { MATCH (t)-[:MentionedIn]->(:Document) }
  AND (
    CAST(split_part(p.birth_date, '/', 1) AS INT64) > 1964
    OR CAST(split_part(p.birth_date, '/', 1) AS INT64) = 1964
    OR (
      CAST(split_part(p.birth_date, '/', 1) AS INT64) = 1963
      AND (
        CAST(split_part(p.birth_date, '/', 2) AS INT64) > 10
        OR (
          CAST(split_part(p.birth_date, '/', 2) AS INT64) = 10
          AND CAST(split_part(p.birth_date, '/', 3) AS INT64) >= 15
        )
      )
    )
  )
RETURN t.team_name AS col1, AVG(CAST(p.mvp_awards AS DOUBLE)) AS col2
